import Foundation

/// Rough growth guidelines for a species (data in GrowthData.swift, generated by
/// scripts/make-growth.py). Mirrors web/js/growth.js. Grams and months throughout.
public struct GrowthGuide: Sendable {
    public struct Target: Sendable, Equatable {
        public let grams: Double
        public let months: Int
    }

    public struct Stage: Sendable, Equatable {
        /// Upper weight limit; `nil` for the last (adult) stage.
        public let upTo: Double?
        public let label: String
        public let minDays: Int
        public let maxDays: Int

        public var intervalDescription: String {
            minDays == maxDays ? "every \(minDays) days" : "every \(minDays)–\(maxDays) days"
        }
    }

    public struct CurvePoint: Sendable, Equatable {
        public let months: Double
        public let low: Double
        public let high: Double
    }

    public let species: String
    public let hotSpot: String
    public let preyPercent: ClosedRange<Double>
    public let hatchling: ClosedRange<Double>
    public let breedingFemale: Target
    public let breedingMale: Target
    public let stages: [Stage]
    public let curve: [CurvePoint]
    public let tips: [String]

    /// Prey size guideline when a species has no guide.
    public static let defaultPreyPercent: ClosedRange<Double> = 10...15

    public static func guide(for species: String) -> GrowthGuide? {
        all.first { $0.species == species }
    }

    /// Feeding stage for a weight: the first stage whose limit is above it.
    public func stage(for grams: Double) -> Stage? {
        guard grams > 0 else { return nil }
        return stages.first { $0.upTo == nil || grams < $0.upTo! }
    }

    /// Typical weight range at an age, interpolated along the curve; `nil` outside it.
    public func reference(atMonths months: Double) -> ClosedRange<Double>? {
        guard months >= 0 else { return nil }
        for (a, b) in zip(curve, curve.dropFirst()) where months >= a.months && months <= b.months {
            let t = (months - a.months) / (b.months - a.months)
            return (a.low + (b.low - a.low) * t)...(a.high + (b.high - a.high) * t)
        }
        return nil
    }

    public func breedingTarget(isFemale: Bool?) -> Target? {
        switch isFemale {
        case true?: return breedingFemale
        case false?: return breedingMale
        case nil: return nil
        }
    }
}

public enum GrowthComparison: String, Sendable {
    case below, within, above

    public var label: String {
        switch self {
        case .below: return "Below typical"
        case .within: return "On track"
        case .above: return "Above typical"
        }
    }
}

public struct Weighing: Sendable, Equatable {
    public let date: Date
    public let grams: Double

    public init(date: Date, grams: Double) {
        self.date = date
        self.grams = grams
    }
}

public enum Growth {
    static let daysPerMonth = 30.4375

    public static func ageInMonths(from hatch: Date, to date: Date = .now) -> Double {
        date.timeIntervalSince(hatch) / 86400 / daysPerMonth
    }

    public static func compare(_ grams: Double, to range: ClosedRange<Double>?) -> GrowthComparison? {
        guard let range, grams > 0 else { return nil }
        if grams < range.lowerBound { return .below }
        if grams > range.upperBound { return .above }
        return .within
    }

    /// Average growth in grams per week (least-squares slope) over the `windowDays` before the
    /// latest weighing. Needs two or more weighings at least 14 days apart.
    public static func rate(_ weighings: [Weighing], windowDays: Double = 90) -> Double? {
        let points = weighings.filter { $0.grams > 0 }.map { (t: $0.date.timeIntervalSince1970 / 86400, g: $0.grams) }
        guard let latest = points.map(\.t).max() else { return nil }
        let recent = points.filter { $0.t >= latest - windowDays }
        guard recent.count >= 2, let earliest = recent.map(\.t).min(), latest - earliest >= 14 else { return nil }
        let n = Double(recent.count)
        let mt = recent.reduce(0) { $0 + $1.t } / n
        let mg = recent.reduce(0) { $0 + $1.g } / n
        let num = recent.reduce(0) { $0 + ($1.t - mt) * ($1.g - mg) }
        let den = recent.reduce(0) { $0 + ($1.t - mt) * ($1.t - mt) }
        return den > 0 ? num / den * 7 : nil
    }

    /// Suggested prey weight range in grams.
    public static func preyRange(for grams: Double, guide: GrowthGuide?) -> ClosedRange<Double>? {
        guard grams > 0 else { return nil }
        let percent = guide?.preyPercent ?? GrowthGuide.defaultPreyPercent
        return (grams * percent.lowerBound / 100)...(grams * percent.upperBound / 100)
    }

    /// Whole weeks to reach `target`; 0 if already there, `nil` if not growing.
    public static func weeksToTarget(current: Double, target: Double, ratePerWeek: Double?) -> Int? {
        guard current > 0, target > 0 else { return nil }
        if current >= target { return 0 }
        guard let ratePerWeek, ratePerWeek > 0 else { return nil }
        return Int(((target - current) / ratePerWeek).rounded(.up))
    }
}

/// Everything the growth screens show for one snake.
public struct GrowthReport: Sendable {
    public let guide: GrowthGuide?
    public let grams: Double?
    public let ageMonths: Double?
    public let stage: GrowthGuide.Stage?
    public let reference: ClosedRange<Double>?
    public let comparison: GrowthComparison?
    public let rate: Double?
    public let prey: ClosedRange<Double>?
    public let target: GrowthGuide.Target?
    public let weeksToTarget: Int?
    /// Weight by age for charts.
    public let points: [(months: Double, grams: Double)]

    /// `isFemale`: true, false, or nil when unsexed.
    public init(species: String, isFemale: Bool?, hatchDate: Date?, currentWeight: Double?,
                weighings: [Weighing], now: Date = .now) {
        let guide = GrowthGuide.guide(for: species)
        let sorted = weighings.filter { $0.grams > 0 }.sorted { $0.date < $1.date }
        let grams = sorted.last?.grams ?? currentWeight
        let age = hatchDate.map { Growth.ageInMonths(from: $0, to: now) }
        let reference = age.flatMap { guide?.reference(atMonths: $0) }
        let rate = Growth.rate(sorted)
        let target = guide?.breedingTarget(isFemale: isFemale)
        self.guide = guide
        self.grams = grams
        self.ageMonths = age
        self.stage = grams.flatMap { guide?.stage(for: $0) }
        self.reference = reference
        self.comparison = grams.flatMap { Growth.compare($0, to: reference) }
        self.rate = rate
        self.prey = grams.flatMap { Growth.preyRange(for: $0, guide: guide) }
        self.target = target
        self.weeksToTarget = target.flatMap { t in grams.flatMap { Growth.weeksToTarget(current: $0, target: t.grams, ratePerWeek: rate) } }
        self.points = hatchDate.map { hatch in sorted.map { (months: Growth.ageInMonths(from: hatch, to: $0.date), grams: $0.grams) } } ?? []
    }
}
